<?php define('TT_BROWSE_TYPE','event');define('TT_BROWSE_TITLE','Events');define('TT_NAV_ACTIVE','event.php');
require_once __DIR__.'/core.php';require_once __DIR__.'/collection_lib.php';tt_require_login();
$db=tt_db_open(true);[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`name`,p.`scope`,p.`type`,p.`comments`,p.`recipients`,a.`filename` attachment_filename,a.`mime_type` attachment_mime FROM `posts` p LEFT JOIN `post_attachments` a ON a.`post_id`=p.`id` WHERE '.$vis.' AND p.`type`=\'event\' ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 200';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();$calendar=[];$media=[];foreach($rows as &$r){$r['_when']=tt_collection_date($r);$calendar[$r['_when']['date']][]=$r;if(trim((string)$r['attachment_filename'])!=='')$media[]=$r;}unset($r);ksort($calendar,SORT_STRING);
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Events</title></head><body><?php tt_nav(TT_NAV_ACTIVE);?><main class="content"><div class="actions"><a href="create.php?mode=event">Create</a><a href="calls.php?scope=event">Event call</a><a href="post.php?type=event">Search events</a></div><h2>Events · calendar</h2><p class="meta">Dates are detected from explicit date tags/fields, post text, attachment filenames, then the post date as fallback. Use annual, yearly or recurs=yearly for recurrence.</p><section class="event-calendar"><?php foreach($calendar as $date=>$items):?><section class="card event-day"><h3><time datetime="<?=tt_h($date)?>"><?=tt_h(date('D, M j Y',strtotime($date)))?></time></h3><?php foreach($items as $r):?><article><strong><?=tt_h($r['title'])?></strong><p class="meta"><?=tt_h($r['name'])?> · date from <?=tt_h($r['_when']['source'])?><?php if($r['_when']['annual']):?> · yearly · next <?=tt_h($r['_when']['next'])?><?php endif;?></p><p><?=nl2br(tt_h($r['content']))?></p></article><?php endforeach;?></section><?php endforeach;?><?php if(!$calendar):?><article class="card">No events yet.</article><?php endif;?></section><h2>Event attachments</h2><section class="collection-gallery"><?php foreach($media as $r):?><?=tt_collection_attachment_html($r)?><?php endforeach;?><?php if(!$media):?><article class="card">No event attachments yet.</article><?php endif;?></section></main><script src="nsfw-blur.js?v=20260915c" defer></script></body></html>
